import * as React from 'react'

import './shimmer-text.css'

type ShimmerTag = 'p' | 'span' | 'div' | 'h1' | 'h2' | 'h3' | 'h4'

export type ShimmerTextProps = {
    children: React.ReactNode
    as?: ShimmerTag
    /** Seconds per sweep. */
    duration?: number
    /** Colour of the passing highlight. The text colour itself stays `currentColor`. */
    highlight?: string
    className?: string
}

// Real text, never split: screen readers, selection and translation all just work.
const ShimmerText = ({ children, as: Tag = 'span', duration = 2.5, highlight = 'rgba(255, 255, 255, 0.85)', className }: ShimmerTextProps) => (
    <Tag
        className={['rad-fx-shimmer', className].filter(Boolean).join(' ')}
        style={{ '--rad-fx-shimmer-duration': `${duration}s`, '--rad-fx-shimmer-highlight': highlight } as React.CSSProperties}
    >
        {children}
    </Tag>
)

export default ShimmerText

.rad-fx-shimmer {
    background-image: linear-gradient(
        110deg,
        currentcolor 40%,
        var(--rad-fx-shimmer-highlight, rgb(255, 255, 255, 0.85)) 50%,
        currentcolor 60%
    );
    background-size: 250% 100%;
    background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    animation: rad-fx-shimmer var(--rad-fx-shimmer-duration, 2.5s) linear infinite;
}

@keyframes rad-fx-shimmer {
    from { background-position: 100% 0; }
    to { background-position: 0% 0; }
}

/* Forced colours (Windows high contrast) ignore backgrounds: fall back to plain text. */
@media (forced-colors: active) {
    .rad-fx-shimmer { background: none; -webkit-text-fill-color: currentcolor; }
}

@media (prefers-reduced-motion: reduce) {
    .rad-fx-shimmer { animation: none; background-position: 100% 0; }
}

[data-rad-fx-motion='reduce'] .rad-fx-shimmer { animation: none; background-position: 100% 0; }
